#include <iostream>
#include "study_vendor_bridge.cu"
#include <fstream>
#include <iomanip>
#include <vector>
#include <utility>
struct Case{int m,n;std::vector<float>dense,values;std::vector<int64_t>rows,cols;float*dd;float*dv;int64_t*dr;int64_t*dc;void*context;};
int main(){std::cout<<"CuSparseVersion "<<study_sparse_version()<<std::endl;std::vector<Case>cases;std::vector<double>prefix;
 for(auto shape:std::vector<std::pair<int,int>>{{17,19},{65,33}}){Case c;c.m=shape.first;c.n=shape.second;c.rows.push_back(0);
  for(int y=0;y<c.m;++y){for(int x=0;x<c.n;++x){bool nz=y%7!=0&&(y%11==1||(y*13+x*7)%9<2);float v=nz?float((y*5+x*3)%17+1)/8.f:((y%7==0&&x%3==0)?-0.f:0.f);if(nz&&(x+y)%2)v=-v;c.dense.push_back(v);if(v!=0){c.cols.push_back(x);c.values.push_back(v);}}c.rows.push_back(c.cols.size());}
  int64_t nnz=c.cols.size();cudacheck(cudaMalloc(&c.dd,c.dense.size()*4));cudacheck(cudaMalloc(&c.dr,c.rows.size()*8));cudacheck(cudaMalloc(&c.dc,nnz*8));cudacheck(cudaMalloc(&c.dv,nnz*4));cudacheck(cudaMemcpy(c.dd,c.dense.data(),c.dense.size()*4,cudaMemcpyHostToDevice));int status=0;c.context=study_prepare(c.dd,c.dr,c.dc,c.dv,c.m,c.n,nnz,&status);if(status||!c.context)return 3;std::vector<int64_t>actualrows(c.rows.size());cudacheck(cudaMemcpy(actualrows.data(),c.dr,actualrows.size()*8,cudaMemcpyDeviceToHost));if(actualrows!=c.rows)return 4;prefix.insert(prefix.end(),c.dense.begin(),c.dense.end());prefix.insert(prefix.end(),actualrows.begin(),actualrows.end());prefix.insert(prefix.end(),nnz,-1);prefix.insert(prefix.end(),nnz,0);for(double x:{double(c.m),double(c.n),double(nnz),10.})prefix.push_back(x);cases.push_back(std::move(c));
 }
 auto run=[&](Case&c,std::vector<double>&out,bool&ok){size_t nnz=c.cols.size();cudacheck(cudaMemset(c.dc,255,nnz*8));cudacheck(cudaMemset(c.dv,0,nnz*4));cudacheck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int i=0;i<10;++i)if(study_convert(c.context))throw std::runtime_error("convertfailed");cudacheck(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;std::vector<int64_t>rows(c.rows.size()),cols(nnz);std::vector<float>vals(nnz);cudacheck(cudaMemcpy(rows.data(),c.dr,rows.size()*8,cudaMemcpyDeviceToHost));cudacheck(cudaMemcpy(cols.data(),c.dc,nnz*8,cudaMemcpyDeviceToHost));cudacheck(cudaMemcpy(vals.data(),c.dv,nnz*4,cudaMemcpyDeviceToHost));ok=ok&&(rows==c.rows);for(int y=0;y<c.m;++y){std::vector<std::pair<int64_t,float>>pairs;for(int64_t i=rows[y];i<rows[y+1];++i)pairs.emplace_back(cols[i],vals[i]);std::sort(pairs.begin(),pairs.end());for(size_t j=0;j<pairs.size();++j){size_t i=rows[y]+j;cols[i]=pairs[j].first;vals[i]=pairs[j].second;}}ok=ok&&(cols==c.cols)&&(vals==c.values);out.insert(out.end(),rows.begin(),rows.end());out.insert(out.end(),cols.begin(),cols.end());out.insert(out.end(),vals.begin(),vals.end());out.push_back(nnz);return elapsed;};
 for(auto&c:cases){std::vector<double>out;bool ok=true;run(c,out,ok);if(!ok)return 5;}
 for(int trial=1;trial<=5;++trial){auto out=prefix;bool ok=true;double elapsed=0;for(auto&c:cases)elapsed+=run(c,out,ok);std::string name="trial_"+std::to_string(trial)+".bin";std::ofstream f(name,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":0,\"timing_region\":\"sum_two_ten_convert_only_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\""<<name<<"\",\"dtype\":\"float64\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}
 for(auto&c:cases){study_destroy(c.context);cudaFree(c.dd);cudaFree(c.dr);cudaFree(c.dc);cudaFree(c.dv);}}
